function boardAggregateAppendix(){const from=$('#from').value,to=$('#to').value,months=marketAggregates().filter(x=>x.location==='bountiful'&&x.month+'-01'>=from.slice(0,7)+'-01'&&x.month+'-01'<=to.slice(0,7)+'-01').sort((a,b)=>a.month.localeCompare(b.month));if(!months.length)return '<section class="card"><h2>Imported Market aggregates</h2><p class="muted">No synthetic monthly aggregate imports for this period. The main board report continues to show demo service-activity figures.</p><button data-view="imports">Open Data Import Center</button></section>';const full=from.endsWith('-01')&&to===new Date(Number(to.slice(0,4)),Number(to.slice(5,7)),0).toLocaleDateString('en-CA').replace(/\//g,'-');return '<section class="card"><h2>Imported Market aggregates — separate reporting source</h2><p class="muted">Synthetic monthly source totals only. These are not added to or substituted for the board report’s daily service figures. '+(full?'Check month coverage before using any combined totals.':'The selected date range may include partial months; these imported figures represent entire months and must not be treated as date-exact.')+'</p>'+table(['Month','Duplicated HH','Unique HH','Duplicated people','Unique people','New clients','Outside Davis %','Shifts'],months.map(x=>[esc(x.month),fmt(x.duplicated_households),fmt(x.unduplicated_households),fmt(x.duplicated_individuals),fmt(x.unduplicated_individuals),fmt(x.new_clients),fmt(x.outside_davis_percent)+'%',fmt(x.market_shifts)]))+'<p class="muted">Monthly unique households and individuals cannot be summed into period-unique counts. County percentages cannot be averaged without denominators.</p></section>'}
const engagementKey='bfp-demo-engagement-v1';
const engagementMeasures=[['social_views','Social media views','views'],['website_visits','Website visits','visits'],['google_profile_views','Google Business profile views','views'],['google_calls','Google profile calls','calls'],['google_directions','Google directions requests','requests'],['google_searches','Google search appearances','appearances'],['volunteer_hours','Volunteer hours','hours'],['family_night_attendance','Pantry Family Night attendance','attendees'],['sorting_group_hours','Sorting group volunteer hours','hours'],['donor_newsletters_sent','Donor newsletters sent','messages'],['donor_newsletters_opened','Donor newsletter opens','opens'],['donor_newsletters_clicked','Donor newsletter clicks','clicks'],['volunteer_newsletters_sent','Volunteer newsletters sent','messages'],['volunteer_newsletters_opened','Volunteer newsletter opens','opens'],['volunteer_newsletters_clicked','Volunteer newsletter clicks','clicks']];
function engagementRecords(){try{return JSON.parse(localStorage.getItem(engagementKey))||[]}catch{return []}}
function engagementPanel(){const rows=engagementRecords().filter(x=>x.month>=$('#from').value.slice(0,7)&&x.month<=$('#to').value.slice(0,7));const totals=new Map(engagementMeasures.map(([key])=>[key,rows.filter(x=>x.measure===key).reduce((n,x)=>n+x.value,0)]));return '<div class="metrics">'+metric('Social media views',totals.get('social_views'),'Recorded monthly totals')+metric('Website visits',totals.get('website_visits'),'Recorded monthly totals')+metric('Volunteer hours',totals.get('volunteer_hours')+totals.get('sorting_group_hours'),'Includes recorded sorting group hours')+metric('Family Night attendees',totals.get('family_night_attendance'),'Recorded event attendance')+'</div><section class="card"><div class="section-head"><div><h2>Monthly community engagement</h2><p class="muted">Enter synthetic monthly summaries now. The Data Import Center can support source-specific CSVs once samples are approved.</p></div><button id="exportEngagement">Export CSV</button></div><form id="engagementEntry" class="planning-form"><label>Reporting month<input name="month" type="month" value="'+esc($('#to').value.slice(0,7))+'" required></label><label>Measure<select name="measure">'+engagementMeasures.map(([id,name])=>'<option value="'+id+'">'+esc(name)+'</option>').join('')+'</select></label><label>Monthly total<input name="value" type="number" min="0" step="0.01" required></label><label>Source / notes<input name="notes" maxlength="180" placeholder="Demo source or reporting notes"></label><button class="primary" type="submit">Save demo monthly total</button></form><p class="muted">Each month and measure has one current value. Saving the same month and measure replaces the prior value; it does not add it twice. Newsletter opens and clicks are event counts, not unique people. Monthly totals spanning partial dates are not date-exact.</p></section><section class="card"><h2>Recorded monthly measures</h2>'+table(['Month','Measure','Total','Source / notes'],rows.sort((a,b)=>b.month.localeCompare(a.month)).map(x=>[esc(x.month),esc(engagementMeasures.find(m=>m[0]===x.measure)?.[1]||x.measure),fmt(x.value),esc(x.notes||'')]))+'</section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='engagementEntry')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.value=Number(x.value);if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(x.month)||!engagementMeasures.some(m=>m[0]===x.measure)||!Number.isFinite(x.value)||x.value<0){toast('Check month, measure and total.');return}const all=engagementRecords().filter(r=>!(r.month===x.month&&r.measure===x.measure));all.push(x);localStorage.setItem(engagementKey,JSON.stringify(all));render();toast('Demo engagement total saved.');});

const financeKey='bfp-demo-financials-v1',grantKey='bfp-demo-grants-v1';
const money=n=>'$'+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function financeRecords(){try{return JSON.parse(localStorage.getItem(financeKey))||[]}catch{return []}}
function grantRecords(){try{return JSON.parse(localStorage.getItem(grantKey))||[]}catch{return []}}
function financeForPeriod(){return financeRecords().filter(x=>x.month>=$('#from').value.slice(0,7)&&x.month<=$('#to').value.slice(0,7)&&($('#location').value==='all'||x.location===$('#location').value))}
function financialPanel(){const rows=financeForPeriod().sort((a,b)=>b.month.localeCompare(a.month)),sum=k=>rows.reduce((n,x)=>n+Number(x[k]||0),0);return '<div class="metrics">'+metric('Revenue',money(sum('revenue')),'Manual monthly summaries')+metric('Expenses',money(sum('expenses')),'Manual monthly summaries')+metric('Operating result',money(sum('revenue')-sum('expenses')),'Revenue less expenses')+metric('Budget variance',money(sum('budget')-sum('expenses')),'Positive = under expense budget')+'</div><section class="card"><h2>Monthly financial reporting</h2><p class="muted">Synthetic data only. Donations are included in revenue, not added to it. No accounting integration or audit. Partial date filters still select whole monthly records.</p><form id="financeEntry" class="planning-form"><label>Month<input name="month" type="month" required value="'+esc($('#to').value.slice(0,7))+'"></label><label>Location<select name="location"><option value="bountiful">Bountiful</option></select></label><label>Revenue ($)<input name="revenue" type="number" min="0" step=".01" required></label><label>Donations included ($)<input name="donations" type="number" min="0" step=".01" required></label><label>Expenses ($)<input name="expenses" type="number" min="0" step=".01" required></label><label>Expense budget ($)<input name="budget" type="number" min="0" step=".01" required></label><label>Source notes<input name="notes" maxlength="180"></label><button class="primary">Save monthly summary</button></form><p class="muted">Saving the same month replaces its previous totals.</p></section><section class="card"><div class="section-head"><h2>Financial register</h2><button id="exportFinancials">Export CSV</button></div>'+table(['Month','Revenue','Donations within revenue','Expenses','Budget','Net','Notes'],rows.map(x=>[esc(x.month),money(x.revenue),money(x.donations),money(x.expenses),money(x.budget),money(x.revenue-x.expenses),esc(x.notes||'')]))+'</section>'}
function grantsPanel(){const rows=grantRecords(),today=new Date().toISOString().slice(0,10),soon=new Date(Date.now()+30*86400000).toISOString().slice(0,10),sorted=rows.slice().sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));return '<div class="grant-metrics"><div class="grant-metric"><span>TRACKED GRANTS</span><strong>'+fmt(rows.length)+'</strong><small>Applications and opportunities</small></div><div class="grant-metric"><span>AWARDED</span><strong>'+money(rows.filter(x=>x.status==='Awarded').reduce((n,x)=>n+x.awarded,0))+'</strong><small>Confirmed status in demo</small></div><div class="grant-metric"><span>SUBMITTED</span><strong>'+money(rows.filter(x=>x.status==='Submitted').reduce((n,x)=>n+x.requested,0))+'</strong><small>Awaiting a decision</small></div><div class="grant-metric"><span>UPCOMING DEADLINES</span><strong>'+fmt(rows.filter(x=>x.deadline&&x.deadline>=today&&x.deadline<=soon).length)+'</strong><small>Within 30 days</small></div></div><section class="card grant-editor"><div class="grant-editor-heading"><div><span class="grant-eyebrow">GRANT WORKSPACE</span><h2>Add or update a grant</h2><p>Track the opportunity, funding decision, and next follow-up in one place.</p></div><span class="grant-demo-label">Synthetic demo</span></div><form id="grantEntry" class="grant-form" method="post" action="#" onsubmit="event.preventDefault()"><input name="id" type="hidden"><div class="grant-form-section"><h3>Opportunity details</h3><div class="grant-form-grid"><label>Grantor <span class="required">*</span><input name="grantor" required maxlength="120" placeholder="Organization or foundation"></label><label>Opportunity / project <span class="required">*</span><input name="project" required maxlength="120" placeholder="Program or grant name"></label><label>Application date<input name="applied" type="date"></label><label>Status<select name="status"><option>Researching</option><option>Preparing</option><option>Submitted</option><option>Awarded</option><option>Declined</option><option>Closed</option></select></label></div></div><div class="grant-form-section"><h3>Funding and restrictions</h3><div class="grant-form-grid"><label>Amount requested ($) <span class="required">*</span><input name="requested" type="number" min="0" step=".01" required placeholder="0.00"></label><label>Amount awarded ($) <span class="required">*</span><input name="awarded" type="number" min="0" step=".01" value="0" required></label><label class="grant-wide">Restricted purpose<input name="restriction" maxlength="180" placeholder="Optional — what the funds may be used for"></label></div></div><div class="grant-form-section"><h3>Next steps</h3><div class="grant-form-grid"><label>Next deadline<input name="deadline" type="date"></label><label>Next action<input name="next" maxlength="180" placeholder="Follow up, submit report, etc."></label></div></div><div class="grant-form-actions"><button class="primary" type="submit">Save grant</button><button type="reset">Clear form</button><span>Demo tracking only · No automatic notifications or grantmaker connection</span></div></form></section><section class="card grant-register"><div class="section-head"><div><h2>Grant register</h2><p class="muted">All tracked opportunities, with deadlines first.</p></div><button id="exportGrants">Export CSV</button></div>'+(rows.length?table(['Grantor / project','Status','Requested','Awarded','Deadline','Next action','Manage'],sorted.map(x=>[esc(x.grantor)+' / '+esc(x.project),esc(x.status),money(x.requested),money(x.awarded),esc(x.deadline||'—'),esc(x.next||'—'),'<button data-edit-grant="'+esc(x.id)+'">Edit</button> <button data-delete-grant="'+esc(x.id)+'">Delete</button>'])):'<div class="grant-empty"><strong>No grants recorded yet</strong><p>Add your first grant using the form above. It will appear here with its status, funding and next deadline.</p></div>')+'</section>'}
function leadershipAppendix(){const f=financeForPeriod(),g=grantRecords(),sum=k=>f.reduce((n,x)=>n+Number(x[k]||0),0);return '<section class="card no-print"><h2>Leadership source review</h2><p class="muted">Financial and grant summaries are separate from service activity. These fictional manual entries are not verified accounting records, and monthly figures may overlap partial date selections.</p>'+(f.length?table(['Financial measure','Monthly totals'],[['Revenue',money(sum('revenue'))],['Expenses',money(sum('expenses'))],['Donations included in revenue',money(sum('donations'))],['Expense budget',money(sum('budget'))],['Operating result',money(sum('revenue')-sum('expenses'))]]):'<p>No financial summaries in the selected months.</p>')+'<p>Tracked grants: '+g.length+'; awarded: '+money(g.filter(x=>x.status==='Awarded').reduce((n,x)=>n+x.awarded,0))+'. Grant awards are not added to financial revenue.</p><button data-view="financials">Review financials</button> <button data-view="grants">Review grants</button></section>'}
document.addEventListener('submit',e=>{if(!['financeEntry','grantEntry'].includes(e.target.id))return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(e.target.id==='financeEntry'){for(const k of ['revenue','donations','expenses','budget'])x[k]=Number(x[k]);if(!/^20[0-9][0-9]-(0[1-9]|1[0-2])$/.test(x.month)||['revenue','donations','expenses','budget'].some(k=>!Number.isFinite(x[k])||x[k]<0)||x.donations>x.revenue){toast('Check financial totals; donations must be within revenue.');return}const all=financeRecords().filter(y=>!(y.month===x.month&&y.location===x.location));all.push(x);localStorage.setItem(financeKey,JSON.stringify(all));render();toast('Monthly financial summary saved.');return}x.requested=Number(x.requested);x.awarded=Number(x.awarded);if(!x.grantor.trim()||!x.project.trim()||![x.requested,x.awarded].every(n=>Number.isFinite(n)&&n>=0)){toast('Check grant details.');return}x.id=x.id||'grant-'+Date.now();const all=grantRecords().filter(y=>y.id!==x.id);all.push(x);localStorage.setItem(grantKey,JSON.stringify(all));render();toast('Demo grant saved.');});


const reportReviewKey='bfp-demo-board-review-v1';
function reportReview(){try{return JSON.parse(localStorage.getItem(reportReviewKey))||{}}catch{return {}}}
function reportPeriodKey(){return $('#from').value+'|'+$('#to').value+'|'+$('#location').value}
function monthCoverage(){const from=$('#from').value,to=$('#to').value;if(from>to)return {ok:false,reason:'Start date must be on or before end date.'};const monthStart=from.slice(0,7)+'-01',lastDay=new Date(Number(to.slice(0,4)),Number(to.slice(5,7)),0).getDate(),monthEnd=to.slice(0,7)+'-'+String(lastDay).padStart(2,'0');if(from!==monthStart||to!==monthEnd)return {ok:false,reason:'Selected dates do not cover complete calendar months. Monthly imports and financials may include days outside this range.'};return {ok:true,reason:'The selected period covers complete calendar months.'}}
function boardReadiness(){const coverage=monthCoverage(),months=[],start=$('#from').value.slice(0,7),end=$('#to').value.slice(0,7);let y=Number(start.slice(0,4)),m=Number(start.slice(5,7));for(let i=0;i<120&&y*12+m<=Number(end.slice(0,4))*12+Number(end.slice(5,7));i++){months.push(y+'-'+String(m).padStart(2,'0'));m++;if(m===13){m=1;y++}}const imported=marketAggregates().filter(x=>x.location==='bountiful'),financial=financeRecords().filter(x=>x.location==='bountiful'),missingMarket=months.filter(x=>!imported.some(r=>r.month===x)),missingFinance=months.filter(x=>!financial.some(r=>r.month===x)),count=physicalCounts().filter(x=>months.includes(x.month));const checks=[['Period coverage',coverage.ok,coverage.reason],['Market monthly aggregate coverage',missingMarket.length===0,missingMarket.length?'Missing: '+missingMarket.join(', '):'Every month has a synthetic aggregate record'],['Monthly financial coverage',missingFinance.length===0,missingFinance.length?'Missing: '+missingFinance.join(', '):'Every month has a manual financial summary'],['Warehouse physical counts',count.length===months.length,count.length+' of '+months.length+' month(s) have a physical count'],['Narrative reviewed',Object.values(data.notes).every(x=>String(x||'').trim().length>0),'All four narrative fields contain text; staff review is still required'],['Month-end review coverage',months.every(x=>monthClosures().some(c=>c.month===x&&c.location==='bountiful')),months.filter(x=>!monthClosures().some(c=>c.month===x&&c.location==='bountiful')).length+' month(s) without a saved review']];return {checks,months}}
const closeKey='bfp-demo-month-close-v1';
function monthClosures(){try{return JSON.parse(localStorage.getItem(closeKey))||[]}catch{return []}}
const closePrepKey='bfp-demo-month-close-checks-v1';
function closePreparations(){try{const x=JSON.parse(localStorage.getItem(closePrepKey));return Array.isArray(x)?x:[]}catch{return []}}
function closeReadinessPanel(){const month=$('#to').value.slice(0,7),count=physicalCounts().some(x=>x.month===month),fin=financeRecords().some(x=>x.month===month&&x.location==='bountiful'),market=marketAggregates().some(x=>x.month===month&&x.location==='bountiful'),pending=warehouseApprovals().filter(x=>x.month===month&&x.status==='Pending').length,checks=[['Physical count recorded',count],['Financial summary recorded',fin],['Market monthly aggregate recorded',market],['No pending warehouse adjustment reviews',pending===0]],ready=checks.every(x=>x[1]),item=closePreparations().find(x=>x.month===month);return '<section class="card"><h2>Monthly closeout readiness · '+esc(month)+'</h2><p class="muted">This checklist identifies missing inputs before leadership sign-off. A saved preparation is not a locked month or an approved financial statement.</p>'+table(['Check','Result'],checks.map(x=>[esc(x[0]),x[1]?'Present':'Needs review']))+'<p><strong>'+ (ready?'Source checklist complete — review figures before sign-off.':'Outstanding source checks — do not treat this month as closed.')+'</strong></p><form id="closePreparation" class="planning-form"><input type="hidden" name="month" value="'+esc(month)+'"><label>Prepared by (demo)<input name="preparer" maxlength="80" required value="'+esc(item?.preparer||'')+'"></label><label>Open exceptions / comments<input name="notes" maxlength="240" value="'+esc(item?.notes||'')+'"></label><button class="primary">Save closeout preparation</button></form><p class="muted">Prepared: '+esc(item?.date||'Not yet')+'. Saving remains possible even with outstanding checks, so exceptions can be documented.</p><button id="exportClosePreparations">Export closeout preparation CSV</button></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='closePreparation')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.preparer.trim())return;x.date=new Date().toISOString();const rows=closePreparations().filter(y=>y.month!==x.month);rows.push(x);localStorage.setItem(closePrepKey,JSON.stringify(rows));render();toast('Demo closeout preparation saved; month remains unlocked.');});
function closePanel(){const m=$('#to').value.slice(0,7),c=monthClosures().find(x=>x.month===m&&x.location==='bountiful'),count=physicalCounts().find(x=>x.month===m),fin=financeRecords().find(x=>x.month===m&&x.location==='bountiful'),market=marketAggregates().find(x=>x.month===m&&x.location==='bountiful');return '<section class="card"><h2>Month-end preparation · '+esc(m)+'</h2><p class="muted">A demonstration checklist for operational sign-off. Marking a month reviewed does not lock underlying records or constitute financial approval.</p>'+table(['Source','Status'],[['Warehouse physical count',count?'Recorded':'Missing'],['Monthly financial summary',fin?'Recorded':'Missing'],['Market aggregate import',market?'Imported':'Missing'],['Staff review',c?'Reviewed on '+esc(c.date):'Not reviewed']])+'<form id="monthClose" class="planning-form"><input type="hidden" name="month" value="'+esc(m)+'"><label>Reviewed by (demo only)<input name="reviewer" maxlength="80" required value="'+esc(c?.reviewer||'')+'"></label><label>Exception / follow-up notes<input name="notes" maxlength="240" value="'+esc(c?.notes||'')+'"></label><button class="primary">Save month-end review</button></form><p class="muted">Records can still be corrected. Production requires real staff identities, approvals, locking rules, and an audit trail.</p></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='monthClose')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.reviewer.trim())return;x.location='bountiful';x.date=new Date().toLocaleString();const all=monthClosures().filter(y=>!(y.month===x.month&&y.location===x.location));all.push(x);localStorage.setItem(closeKey,JSON.stringify(all));render();toast('Demo month-end review saved.');});

function leadershipCloseoutPanel(){const start=$('#from').value.slice(0,7),end=$('#to').value.slice(0,7),months=[];let year=Number(start.slice(0,4)),month=Number(start.slice(5,7));for(let i=0;i<36&&year*12+month<=Number(end.slice(0,4))*12+Number(end.slice(5,7));i++){months.push(year+'-'+String(month).padStart(2,'0'));month++;if(month===13){month=1;year++}}const prepared=closePreparations(),reviews=monthClosures(),requests=warehouseApprovals(),counts=physicalCounts(),finances=financeRecords(),markets=marketAggregates();return '<section class="card no-print"><h2>Leadership month-end handoff</h2><p class="muted">See which months have source records, preparation notes and outstanding warehouse requests before sharing a board packet. No row is an approved or locked month.</p>'+table(['Month','Sources present','Warehouse requests','Preparation','Staff review'],months.map(m=>{const n=[counts.some(x=>x.month===m),finances.some(x=>x.month===m&&x.location==='bountiful'),markets.some(x=>x.month===m&&x.location==='bountiful')].filter(Boolean).length,pending=requests.filter(x=>x.month===m&&x.status==='Pending').length,prep=prepared.find(x=>x.month===m),review=reviews.find(x=>x.month===m&&x.location==='bountiful');return [esc(m),n+'/3',pending?pending+' pending':'None pending',prep?'Prepared by '+esc(prep.preparer):'Not prepared',review?'Reviewed by '+esc(review.reviewer):'Not reviewed']}))+'<p class="muted">Sources present means records exist, not that their values were verified. This summary uses synthetic browser-local demo data.</p><button id="exportLeadershipCloseout">Export month-end handoff CSV</button></section>'}
function boardFinalReviewPanel(){const {checks,months}=boardReadiness(),opts=currentBoardOptions(),pending=warehouseApprovals().filter(x=>months.includes(x.month)&&x.status==='Pending'),missing=checks.filter(x=>!x[1]),review=reportReview()[reportPeriodKey()],notes=String(review?.notes||'').trim(),warnings=[];if(!opts.sources)warnings.push('Reporting sources appendix is excluded');if(!notes)warnings.push('Board preparation notes have not been saved');if(pending.length)warnings.push(pending.length+' warehouse adjustment request(s) still pending');if($('#location').value==='all')warnings.push('Organization-wide view currently includes only the active Bountiful location');const status=missing.length||pending.length?'Needs attention':warnings.length?'Ready for human review with cautions':'Ready for human review';return '<section class="card no-print"><h2>Final board packet review</h2><p class="muted">An automated preparation screen, not approval or publication. A reviewer must verify source figures, narrative and layout before distributing a report.</p><p><strong>Preparation status: '+esc(status)+'</strong></p>'+table(['Review category','Finding','Next step'],[['Source coverage',missing.length+' missing / incomplete',missing.length?'Resolve missing checks below':'Confirm actual figures against sources'],['Warehouse exceptions',pending.length+' pending',pending.length?'Review warehouse queue':'Confirm no unposted adjustments'],['Packet selection',Object.values(opts).filter(Boolean).length+' of 3 pages selected',opts.sources?'Review selected pages':'Consider restoring source appendix'],['Human preparation notes',notes?'Saved':'Not saved',notes?'Review notes for accuracy':'Save reviewer notes below']].map(x=>x.map(esc)))+(missing.length?'<h3>Outstanding source checks</h3>'+table(['Check','Detail'],missing.map(x=>[esc(x[0]),esc(x[2])])):'<p class="muted">All automated source-presence checks passed. This does not verify their accuracy.</p>')+(warnings.length?'<h3>Review cautions</h3><p>'+warnings.map(esc).join('; ')+'</p>':'')+'<div class="toolbar"><button id="boardGoPreview" class="primary">Preview selected packet</button><button id="exportBoardReviewChecklist">Export final review checklist</button></div><p class="muted">Printing remains available even with warnings so staff can review drafts. The PDF must be approved outside this public demo.</p></section>'}
function boardReviewPanel(){const {checks}=boardReadiness(),review=reportReview(),key=reportPeriodKey(),item=review[key],ready=checks.filter(x=>x[1]).length;return '<section class="card no-print"><div class="section-head"><div><h2>Board packet preparation checklist</h2><p class="muted">Automated source checks flag gaps; they do not certify the accuracy of financial or operational figures.</p></div><span class="status">'+ready+' / '+checks.length+' checks</span></div>'+table(['Check','Status','Detail'],checks.map(x=>[esc(x[0]),x[1]?'Available':'Needs review',esc(x[2])]))+'<div class="notice"><strong>Source boundaries</strong>Household service activity, PantrySoft aggregates, inventory, grants, and financial summaries remain separate. Monthly unduplicated totals cannot be summed into a period-unique count. Never treat a draft or review acknowledgement as an audit.</div><label>Reviewer / preparation notes<textarea id="boardReviewNotes" rows="3" maxlength="500" placeholder="Synthetic demo notes">'+esc(item?.notes||'')+'</textarea></label><button id="saveBoardReview">Save review notes</button> <button id="exportBoardPacket">Export board data packet CSV</button><p class="muted">Review notes are stored only in this browser for the selected date range and location. No staff authentication or formal approval workflow is active.</p></section>'}
function boardPacketRows(){const s=stats(),from=$('#from').value,to=$('#to').value,loc=$('#location').value,base=[['section','metric','period_or_month','location','value','source','note'],['Service','Unique households',from+' to '+to,loc,s.households,'Simulated visit records','Period-distinct households'],['Service','Service visits',from+' to '+to,loc,s.visits,'Simulated visit records','Duplicated visits'],['Service','Person-visits',from+' to '+to,loc,s.people,'Simulated visit records','Not distinct people'],['Food','Incoming lb',from+' to '+to,loc,s.incoming,'Simulated food receipts',''],['Food','Client service lb',from+' to '+to,loc,s.out,'Simulated visit records','Do not add to truck loads'],['Pantry Packs','Completed',from+' to '+to,loc,s.packs,'Simulated packs','']];for(const x of marketAggregates().filter(x=>x.month>=from.slice(0,7)&&x.month<=to.slice(0,7))){for(const k of ['duplicated_households','unduplicated_households','duplicated_individuals','unduplicated_individuals','new_clients','outside_davis_percent','market_shifts'])base.push(['Market aggregate',k,x.month,x.location,x[k],'Synthetic monthly CSV import','Full-month total; not added to service metrics'])}for(const x of financeForPeriod()){for(const k of ['revenue','donations','expenses','budget'])base.push(['Financials',k,x.month,x.location,x[k],'Manual monthly summary',k==='donations'?'Included within revenue':'Not audited'])}for(const x of grantRecords())base.push(['Grants',x.grantor+' / '+x.project,x.deadline||'',loc,x.awarded,'Demo grant register','Award amounts not added to revenue']);return base}


function reportingMonths(){const a=$('#from').value.slice(0,7),b=$('#to').value.slice(0,7),out=[];let y=Number(a.slice(0,4)),m=Number(a.slice(5,7));for(let i=0;i<120&&y*12+m<=Number(b.slice(0,4))*12+Number(b.slice(5,7));i++){out.push(y+'-'+String(m).padStart(2,'0'));if(++m===13){m=1;y++}}return out}
function monthlyVisitTrend(){const months=reportingMonths();return months.map(month=>{const visits=data.visits.filter(x=>x.date.slice(0,7)===month&&($('#location').value==='all'||x.location===$('#location').value));return {month,visits:visits.length,people:visits.reduce((n,x)=>n+Number(x.size||0),0),households:new Set(visits.map(x=>x.household)).size,pounds:visits.reduce((n,x)=>n+Number(x.pounds||0),0)}})}
function historicalTrends(){const rows=monthlyVisitTrend();return '<section class="card"><h2>Monthly service trends</h2><p class="muted">Fictional demo service records only. Each row represents a full calendar month even if the selected dates are partial. Monthly unique households are distinct within that month, not additive across months.</p>'+table(['Month','Service visits','Unique households within month','Person-visits','Direct service pounds'],rows.map(x=>[esc(x.month),fmt(x.visits),fmt(x.households),fmt(x.people),fmt(x.pounds)]))+'<button id="exportVisitTrends">Export monthly trends CSV</button></section>'}


function yearOverYearTrend(){const months=reportingMonths(),loc=$('#location').value,agg=marketAggregates();return months.map(month=>{const prev=String(Number(month.slice(0,4))-1)+month.slice(4),a=agg.find(x=>x.month===month&&(loc==='all'||x.location===loc)),b=agg.find(x=>x.month===prev&&(loc==='all'||x.location===loc));return {month,prev,current:a?.duplicated_households??null,previous:b?.duplicated_households??null,change:a&&b&&b.duplicated_households>0?Math.round((a.duplicated_households-b.duplicated_households)/b.duplicated_households*1000)/10:null}})}
function yearOverYearPanel(){const rows=yearOverYearTrend();return '<section class="card"><h2>Year-over-year Market comparison</h2><p class="muted">Compares synthetic imported PantrySoft monthly duplicated-household totals for the same calendar month in consecutive years. Missing months are shown as unavailable, never zero. No current-versus-prior comparisons are inferred from daily visit records.</p>'+table(['Current month','Prior-year month','Current duplicated households','Prior-year duplicated households','Change'],rows.map(x=>[esc(x.month),esc(x.prev),x.current===null?'No import':fmt(x.current),x.previous===null?'No import':fmt(x.previous),x.change===null?'Not comparable':(x.change>0?'+':'')+x.change+'%']))+'<button id="exportYoY">Export year-over-year CSV</button></section>'}


function programBreakdown(){const months=new Set(reportingMonths()),loc=$('#location').value,visits=data.visits.filter(x=>months.has(x.date.slice(0,7))&&(loc==='all'||x.location===loc));const groups=new Map();for(const v of visits){const name=v.channel||v.program||'Unspecified service';if(!groups.has(name))groups.set(name,{name,visits:0,people:0,pounds:0,households:new Set()});const x=groups.get(name);x.visits++;x.people+=Number(v.size||0);x.pounds+=Number(v.pounds||0);x.households.add(v.household)}return [...groups.values()].map(x=>({name:x.name,visits:x.visits,people:x.people,pounds:x.pounds,households:x.households.size})).sort((a,b)=>b.visits-a.visits)}
function programBreakdownPanel(){const rows=programBreakdown(),total=rows.reduce((n,x)=>n+x.visits,0);return '<section class="card"><h2>Program and service-channel breakdown</h2><p class="muted">Grouped from fictional service-visit records by recorded channel. Unique households are within each channel only; a household visiting multiple channels appears in multiple rows. Percentages use service visits as the denominator. Imported monthly Market aggregates, off-site location summaries, and Pantry Packs are not silently added to these totals.</p>'+table(['Service channel','Visits','Share of visits','Households within channel','Person-visits','Pounds'],rows.map(x=>[esc(x.name),fmt(x.visits),total?(x.visits/total*100).toFixed(1)+'%':'—',fmt(x.households),fmt(x.people),fmt(x.pounds)]))+'<button id="exportPrograms">Export program breakdown CSV</button></section>'}


function monthQuality(){const months=reportingMonths(),agg=marketAggregates(),fin=financeRecords(),counts=physicalCounts(),reviews=monthClosures(),loc=$('#location').value;return months.map(month=>{const market=agg.some(x=>x.month===month&&(loc==='all'||x.location===loc)),finance=fin.some(x=>x.month===month&&(loc==='all'||x.location===loc)),inventory=counts.some(x=>x.month===month),review=reviews.some(x=>x.month===month);return {month,market,finance,inventory,review,complete:[market,finance,inventory,review].filter(Boolean).length}})}
function qualityPanel(){const rows=monthQuality(),yes=x=>x?'Recorded':'Missing';return '<section class="card"><h2>Historical data coverage</h2><p class="muted">Monthly source coverage is a planning aid, not a data audit. Inventory and review records currently represent Bountiful only. Other-location completeness is not supported in this public demo.</p>'+table(['Month','Market import','Financial summary','Physical count','Month-end review','Coverage'],rows.map(x=>[esc(x.month),yes(x.market),yes(x.finance),yes(x.inventory),yes(x.review),x.complete+'/4']))+'<button id="exportQuality">Export coverage CSV</button></section>'}


function financialTrendRows(){const rows=financeRecords(),loc=$('#location').value;return reportingMonths().map(month=>{const matches=rows.filter(x=>x.month===month&&(loc==='all'||x.location===loc));return {month,available:matches.length>0,revenue:matches.reduce((n,x)=>n+Number(x.revenue||0),0),expenses:matches.reduce((n,x)=>n+Number(x.expenses||0),0),budget:matches.reduce((n,x)=>n+Number(x.budget||0),0),donations:matches.reduce((n,x)=>n+Number(x.donations||0),0)}})}
function financialTrendPanel(){const rows=financialTrendRows();return '<section class="card"><h2>Monthly financial trend</h2><p class="muted">Fictional manual full-month summaries. A missing month is unavailable, not $0. Donations are included in revenue. These totals are not audited and are not automatically reconciled with grants.</p>'+table(['Month','Revenue','Expenses','Operating result','Expense budget','Budget variance'],rows.map(x=>[esc(x.month),x.available?money(x.revenue):'No summary',x.available?money(x.expenses):'—',x.available?money(x.revenue-x.expenses):'—',x.available?money(x.budget):'—',x.available?money(x.budget-x.expenses):'—']))+'<button id="exportFinanceTrend">Export financial trend CSV</button></section>'}


function serviceComparisonRows(){const months=reportingMonths(),loc=$('#location').value,all=data.visits.filter(x=>loc==='all'||x.location===loc);const totals=m=>all.filter(x=>x.date.slice(0,7)===m).length;return months.map(month=>{let y=Number(month.slice(0,4)),m=Number(month.slice(5,7))-1;if(!m){m=12;y--}const prior=y+'-'+String(m).padStart(2,'0'),current=totals(month),previous=totals(prior);return {month,prior,current,previous,change:previous?Math.round((current-previous)/previous*1000)/10:null}})}
function serviceComparisonPanel(){const rows=serviceComparisonRows();return '<section class="card"><h2>Month-over-month service comparison</h2><p class="muted">Synthetic visit counts by full calendar month. Previous month is calculated even when outside the selected range. A zero baseline cannot produce a meaningful percentage change. Counts are from the demo visit ledger, not PantrySoft aggregate imports.</p>'+table(['Month','Previous month','Current visits','Previous visits','Change'],rows.map(x=>[esc(x.month),esc(x.prior),fmt(x.current),fmt(x.previous),x.change===null?'Not comparable':(x.change>0?'+':'')+x.change+'%']))+'<button id="exportServiceCompare">Export comparison CSV</button></section>'}

function summary(s){return table(['Measure','Selected period'],[['Unique households',fmt(s.households)],['Service visits',fmt(s.visits)],['Individuals served (person-visits)',fmt(s.people)],['Food directly to clients (lb)',fmt(s.out)],['Food received (lb)',fmt(s.incoming)],['Grocery Rescue (lb)',fmt(s.rescue)],['Pantry Packs completed',fmt(s.packs)]])}
function printableBoardAppendix(){const result=boardReadiness(),f=financeForPeriod(),sum=k=>f.reduce((n,x)=>n+Number(x[k]||0),0),grants=grantRecords(),review=reportReview()[reportPeriodKey()],months=result.months,market=marketAggregates().filter(x=>months.includes(x.month)&&x.location==='bountiful'),closed=monthClosures().filter(x=>months.includes(x.month)&&x.location==='bountiful');return '<section class="report-page report-appendix"><div class="report-masthead"><div class="report-brand"><img src="logo.png" alt="Bountiful Food Pantry"><div><strong>BOUNTIFUL FOOD PANTRY</strong><span>Board briefing · Reporting sources</span></div></div><span class="report-demo">SYNTHETIC DEMO</span></div><div class="report-page-title"><span class="report-kicker">04 / REPORTING SOURCES</span><h2>What is behind the numbers.</h2><p>Reporting period: '+esc($('#from').value)+' through '+esc($('#to').value)+'</p></div><h3>Source readiness</h3>'+table(['Source check','Status'],result.checks.map(x=>[esc(x[0]),x[1]?'Available':'Review needed: '+esc(x[2])]))+'<h3>Market source coverage</h3><p>'+market.length+' monthly synthetic aggregate records for '+months.length+' calendar months. Monthly unique households or people are not additive across months; source aggregates are not combined with simulated service-visit totals.</p><h3>Monthly financial summaries</h3>'+(f.length?table(['Measure','Manual demo total'],[['Revenue',money(sum('revenue'))],['Expenses',money(sum('expenses'))],['Operating result',money(sum('revenue')-sum('expenses'))],['Donations (included in revenue)',money(sum('donations'))],['Expense budget',money(sum('budget'))]]):'<p>No financial summaries available for the selected months.</p>')+'<p>These totals are full-month entries and are not audited. They may include dates outside a partial-month report range. Grant awards are not added to revenue.</p><h3>Grants and inventory</h3><p>'+grants.length+' grants tracked; '+grants.filter(x=>x.status==='Awarded').length+' marked awarded. '+closed.length+' of '+months.length+' month-end reviews recorded. Review entries do not lock records or constitute formal approval.</p><h3>Preparation notes</h3><p>'+(review?.notes?esc(review.notes):'No reviewer notes recorded for this reporting period.')+'</p><p class="muted">This appendix documents demonstration reporting sources and gaps. It is not an audit, verification, or production sign-off.</p></section>'}

const boardOptionsKey='bfp-demo-board-options-v1';
function boardOptions(){try{return JSON.parse(localStorage.getItem(boardOptionsKey))||{}}catch{return {}}}
function currentBoardOptions(){return Object.assign({impact:true,narrative:true,sources:true},boardOptions()[reportPeriodKey()]||{})}
function boardPresentationIntro(){const checks=boardReadiness().checks,missing=checks.filter(x=>!x[1]).length;return '<section class="board-workspace-heading no-print"><div><span class="eyebrow">REPORTING WORKSPACE</span><h2>Board report</h2><p>Review the figures and narrative for the selected period, then preview or print the report.</p><span class="board-source-status">'+esc(missing?missing+' source checks need attention':'Source-presence checks complete · verify accuracy before sharing')+'</span></div><button class="primary" id="boardGoPreview">'+(preview?'Refresh preview':'Preview report')+' →</button></section>'}
function boardCustomizePanel(){const opts=currentBoardOptions(),sections=[['impact','Community impact and program breakdown'],['narrative','Leadership outlook and narrative'],['sources','Reporting sources appendix']];return '<section class="card no-print"><h2>Customize this board packet</h2><p class="muted">Choose the pages that appear in the printable preview. Choices are stored in this browser for the selected dates and location.</p><form id="boardOptionsForm" class="planning-form">'+sections.map(([id,label])=>'<label><input type="checkbox" name="'+id+'" '+(opts[id]?'checked':'')+'> '+esc(label)+'</label>').join('')+'<button class="primary">Save report sections</button></form><p class="muted">Keep the reporting sources appendix for transparency. Hiding it does not change or validate any numbers.</p></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='boardOptionsForm')return;e.preventDefault();const x=Object.fromEntries(['impact','narrative','sources'].map(k=>[k,!!e.target.elements.namedItem(k).checked]));if(!Object.values(x).some(Boolean)){toast('Keep at least one report section.');return}const all=boardOptions();all[reportPeriodKey()]=x;localStorage.setItem(boardOptionsKey,JSON.stringify(all));render();toast('Board packet page choices saved.');});
function board(s){
const period=new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric'}),pretty=date=>date?period.format(new Date(date+'T12:00:00')):'Date not selected';
const range=pretty($('#from').value)+' – '+pretty($('#to').value),location=$('#location').value==='all'?'Organization-wide · Bountiful active':'Bountiful';
const pct=n=>s.visits?Math.round(n/s.visits*100):0,colors=['#2a8a42','#1f63b2','#498ab5','#bf643e'];
const mark=(page,title)=>`<div class="report-masthead"><div class="report-brand"><img src="logo.png" alt="Bountiful Food Pantry"><div><strong>BOUNTIFUL FOOD PANTRY</strong><span>Board briefing · ${esc(title)}</span></div></div><span class="report-demo">SYNTHETIC DEMO</span></div>`;
const bottom=(n)=>`<div class="report-footer"><span>${esc(location)} · ${esc(range)}</span><strong>BOUNTIFUL / ${String(n).padStart(2,'0')}</strong></div>`;
const note=(key,label,number)=>`<section class="report-note"><div class="report-note-label"><span>${number}</span><h3>${label}</h3></div><p>${esc(data.notes[key])}</p></section>`;
return `<article class="paper board-brief"><section class="report-page report-impact">${mark(1,'Community impact')}<div class="report-cover"><div><span class="report-kicker">COMMUNITY IMPACT</span><h1>Good food.<br>Greater reach.</h1><p class="report-period">${esc(range)}</p><p class="report-scope">${esc(location)}</p></div><div class="report-cover-number"><strong>${fmt(s.households)}</strong><span>unique households<br>reached this period</span><div class="report-cover-rule"></div><small>Built from recorded service activity</small></div></div><div class="report-highlights"><div><span class="report-stat-icon">${iconFor('clients')}</span><strong>${fmt(s.visits)}</strong><span>service visits</span></div><div><span class="report-stat-icon">${iconFor('food')}</span><strong>${fmt(s.out)}</strong><span>pounds directly to households</span></div><div><span class="report-stat-icon">${iconFor('packs')}</span><strong>${fmt(s.packs)}</strong><span>Pantry Packs completed</span></div></div><div class="report-section-heading"><span>01 / SERVICE</span><h2>Every program. A shared purpose.</h2><p>Service visits by program in the selected period.</p></div><div class="report-service-mix">${channels.map((c,i)=>{const n=s.v.filter(x=>x.program===c).length;return `<div class="report-channel"><div class="report-channel-label"><strong>${c}</strong><span>${fmt(n)} visits <b>${pct(n)}%</b></span></div><div class="report-track"><i style="width:${s.visits?n/s.visits*100:0}%;background:${colors[i]}"></i></div></div>`}).join('')}</div><p class="report-caption">${fmt(s.people)} person-visits recorded. A household can receive service more than once; visits and unique households are different measures. Percentages are rounded.</p><section class="report-director"><span class="report-kicker">FROM THE DIRECTOR</span><h2>Perspective behind the numbers</h2><p>${esc(data.notes.director)}</p></section>${bottom(1)}</section><section class="report-page">${mark(2,'Operations & reach')}<div class="report-page-title"><span class="report-kicker">02 / OPERATIONS & REACH</span><h2>Food moving.<br>Communities connected.</h2><p>Recorded food movement and household geography.</p></div><div class="report-food-flow"><div><span>FOOD RECEIVED</span><strong>${fmt(s.incoming)}<small> lb</small></strong><p>Total incoming food</p></div><div><span>GROCERY RESCUE</span><strong>${fmt(s.rescue)}<small> lb</small></strong><p>Included in food received</p></div><div><span>DIRECT TO HOUSEHOLDS</span><strong>${fmt(s.out)}<small> lb</small></strong><p>Recorded with service visits</p></div></div><div class="report-section-heading"><h2>Service by program</h2></div>${table(['Program','Visits','Person-visits','Food (lb)'],channels.map(c=>{let v=s.v.filter(x=>x.program===c);return[c,fmt(v.length),fmt(v.reduce((n,x)=>n+x.size,0)),fmt(v.reduce((n,x)=>n+x.pounds,0))]}))}<div class="report-section-heading"><h2>Where households call home</h2><p>Residential geography, across all service channels.</p></div>${table(['Community','Unique households','Service visits'],cities.map(c=>{let v=s.v.filter(x=>x.city===c);return[c,fmt(new Set(v.map(x=>x.household)).size),fmt(v.length)]}))}<div class="report-program-strip"><span class="report-stat-icon">${iconFor('packs')}</span><div><h3>Pantry Packs</h3><p>Completed packs in this period</p></div><strong>${fmt(s.packs)}</strong></div><p class="report-caption">Food received and distributed are separate movements. These figures do not represent a physical inventory count. Northern Davis is planned and has no activity in this report.</p>${bottom(2)}</section><section class="report-page report-outlook">${mark(3,'Leadership outlook')}<div class="report-page-title"><span class="report-kicker">03 / LEADERSHIP OUTLOOK</span><h2>The work ahead.</h2><p>Leadership commentary, context, and reporting inputs.</p></div>${note('client','Client services','01')}${note('operations','Operations','02')}${note('capital','Capital campaign update','03')}<section class="report-external"><div class="report-external-heading"><span class="report-stat-icon">${iconFor('clients')}</span><div><h3>Volunteer contribution</h3><span>${s.volunteerData?'Connected demo · approved service':'External summary · synthetic demonstration'}</span></div><strong>${fmt(s.volunteerData?s.volunteerData.hours:data.volunteer)}<small> hours</small></strong></div><p>${s.volunteerData?`${fmt(s.volunteerData.people)} volunteers contributed approved time in the selected dates and location. Calculated from the volunteer prototype in this browser; pending time and planned bookings are excluded.`:'This is a separate, undated monthly summary. It is not filtered by this report’s dates. The existing volunteer system remains the source of truth.'}</p></section><section class="report-basis"><h3>About this report</h3><p>All figures and narratives are synthetic demonstration content. Operational measures are calculated from records within the selected dates and location. “Individuals served” means person-visits, including repeat service. Financial and development figures are not included because an approved source has not been connected.</p></section>${bottom(3)}</section>${printableBoardAppendix()}</article>`;
}


