function barrelPanel(){const rows=barrelRequests();return '<section class="card"><div class="section-head"><div><h2>Barrels and Gaylords · request planning</h2><p class="muted">Internal demonstration of the requested approval workflow. Public website requests and email notifications are not connected.</p></div><button id="exportBarrels">Export requests</button></div><form id="barrelEntry" class="planning-form"><label>Organization / requester<input name="requester" maxlength="100" required placeholder="Fictional organization"></label><label>Container<select name="kind"><option>Barrel</option><option>Gaylord</option></select></label><label>Quantity<input name="quantity" type="number" min="1" max="500" value="1" required></label><label>Requested date<input name="date" type="date" required></label><label>Movement<select name="movement"><option>Dropoff</option><option>Pickup</option></select></label><button class="primary">Add demo request</button></form>'+table(['Requester','Container','Qty','Date','Movement','Status','Review'],rows.map(x=>[esc(x.requester),esc(x.kind),fmt(x.quantity),esc(x.date),esc(x.movement),esc(x.status),'<button data-barrel-toggle="'+esc(x.id)+'">'+(x.status==='Pending'?'Approve':x.status==='Approved'?'Complete':'Reopen')+'</button>']))+'</section>'}
