function warehouseReviewFlags(){const from=$('#from').value,to=$('#to').value,food=data.food.filter(x=>x.date>=from&&x.date<=to),out=data.outgoing.filter(x=>x.date>=from&&x.date<=to),runs=truckRuns().filter(x=>x.date>=from&&x.date<=to),invalid=[...food.map(x=>({kind:'Receipt',x})),...out.map(x=>({kind:'Transfer',x}))].filter(r=>!Number.isFinite(Number(r.x.pounds))||Number(r.x.pounds)<0),unlabeled=out.filter(x=>!String(x.partner||x.destination||'').trim()),unmatched=runs.filter(x=>[x.loaded,x.returned,x.transferred,x.disposed,x.distributed].some(v=>v!==undefined&&v!==null&&v!==''&&!Number.isFinite(Number(v)))||Math.abs(Number(x.loaded||0)-Number(x.returned||0)-Number(x.transferred||0)-Number(x.disposed||0)-Number(x.distributed||0))>0.02);return '<section class="card"><h2>Warehouse exception review</h2><p class="muted">Potential entry issues to review before monthly reporting. These checks do not validate official categories or prove stock balances.</p>'+table(['Check','Flagged records','What to verify'],[['Missing outgoing destination',unlabeled.length,'Partner / receiving pantry'],['Negative or invalid receipt / transfer weights',invalid.length,'Weight and source entry'],['Truck run weight differences',unmatched.length,'Loaded minus returned, transfers, disposal and distributed']].map(x=>[esc(x[0]),fmt(x[1]),esc(x[2])]))+'</section>'}

function warehouseMovementReview(){const from=$('#from').value,to=$('#to').value,receipts=data.food.filter(x=>x.date>=from&&x.date<=to),partners=data.outgoing.filter(x=>x.date>=from&&x.date<=to),other=inventoryRecords().filter(x=>x.date>=from&&x.date<=to),sum=a=>a.reduce((n,x)=>n+Number(x.pounds||0),0),rows=[['Food received',receipts.length,sum(receipts),'Incoming food receipts'],['Partner transfers',partners.length,sum(partners),'Outgoing partner records'],...['disposal','adjustment'].map(type=>{const x=other.filter(r=>r.type===type);return [type==='disposal'?'Disposed food':'Inventory adjustments',x.length,sum(x),'Separate warehouse movement ledger']})];return '<section class="card"><div class="section-head"><div><h2>Warehouse movement review</h2><p class="muted">Review recorded food movements before preparing the month-end count. These totals do not establish closing inventory.</p></div><button id="exportWarehouseReview">Export CSV</button></div>'+table(['Movement','Records','Pounds','Source'],rows.map(x=>x.map((v,i)=>i===1||i===2?fmt(v):esc(v))))+'</section>'}
function warehouseMovementRows(){const from=$('#from').value,to=$('#to').value;return [['movement','date','category','partner_or_note','pounds','source'],...data.food.filter(x=>x.date>=from&&x.date<=to).map(x=>['Incoming',x.date,x.category||'',x.partner||'',x.pounds,'Food receipts']),...data.outgoing.filter(x=>x.date>=from&&x.date<=to).map(x=>['Partner transfer',x.date,x.category||'',x.partner||x.destination||'',x.pounds,'Outgoing food']),...inventoryRecords().filter(x=>x.date>=from&&x.date<=to).map(x=>[x.type||'Movement',x.date,x.category||'',x.notes||'',x.pounds,'Warehouse ledger'])]}

function warehouseCountSheet(){const month=$('#to').value.slice(0,7),categories=[...new Set([...data.food.map(x=>x.category),...data.outgoing.map(x=>x.category)].filter(Boolean))].sort(),rows=categories.map(c=>'<tr><td style="padding:12px;border:1px solid #888">'+esc(c)+'</td><td style="padding:12px;border:1px solid #888"></td><td style="padding:12px;border:1px solid #888"></td></tr>').join(''),w=window.open('','_blank');if(!w){toast('Allow pop-ups to print the count sheet.');return}w.document.write('<!doctype html><html><head><title>Bountiful inventory count sheet</title></head><body style="font:16px Arial,sans-serif;margin:40px"><h1>Bountiful Food Pantry</h1><h2>Physical inventory count sheet · '+esc(month)+'</h2><p>DEMO TEMPLATE — CATEGORIES FROM DEMO RECEIPTS ONLY; NOT THE OFFICIAL FOOD-BANK SEVEN CATEGORIES</p><p>Location: ___________________ Date counted: ___________________</p><table style="width:100%;border-collapse:collapse"><tr><th style="border:1px solid #888;padding:12px">Category</th><th style="border:1px solid #888;padding:12px">Counted weight (lb)</th><th style="border:1px solid #888;padding:12px">Notes</th></tr>'+rows+'</table><p>Counted by: ___________________ Reviewed by: ___________________</p><p>This sheet does not certify or lock inventory balances.</p><script>window.print()<\/script></body></html>');w.document.close()}

const warehouseApprovalKey='bfp-demo-warehouse-approvals-v1';
function warehouseApprovals(){try{const rows=JSON.parse(localStorage.getItem(warehouseApprovalKey));return Array.isArray(rows)?rows:[]}catch{return []}}
function warehouseApprovalPanel(){const month=$('#to').value.slice(0,7),rows=warehouseApprovals().filter(x=>x.month===month),counts=physicalCounts().find(x=>x.month===month),variance=counts?'Physical count recorded; review variance in reconciliation above':'No physical count recorded';return '<section class="card"><h2>Warehouse adjustment approval queue · '+esc(month)+'</h2><p class="muted">A browser-local rehearsal of a two-step adjustment review. Submitting or approving here does NOT change inventory totals, create a secure approval, or lock a period.</p><p class="muted">'+esc(variance)+'</p><form id="warehouseApprovalRequest" class="planning-form"><input type="hidden" name="month" value="'+esc(month)+'"><label>Proposed signed adjustment (lb)<input type="number" step=".01" name="pounds" required placeholder="Example: -12.5"></label><label>Reason / count evidence<input name="reason" required maxlength="240" placeholder="Explain the variance"></label><label>Requested by (demo)<input name="requester" required maxlength="80"></label><button class="primary">Submit for review</button></form>'+table(['Proposed adjustment','Requested by','Reason','Status','Review'],rows.map(x=>[esc(String(x.pounds))+' lb',esc(x.requester),esc(x.reason),esc(x.status)+(x.reviewer?' · '+esc(x.reviewer):''),x.status==='Pending'?'<button data-warehouse-review="'+esc(x.id)+'">Mark reviewed</button>':'—']))+'<p class="muted">A production workflow must verify identities, enforce different requester/approver accounts, record immutable history, and apply only approved adjustments through controlled posting.</p><button id="exportWarehouseApprovals">Export adjustment requests CSV</button></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='warehouseApprovalRequest')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));const n=Number(x.pounds);if(!Number.isFinite(n)||n===0||!x.reason.trim()||!x.requester.trim())return;x.pounds=n;x.id='WA-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);x.status='Pending';x.created=new Date().toISOString();const rows=warehouseApprovals();rows.push(x);localStorage.setItem(warehouseApprovalKey,JSON.stringify(rows));render();toast('Demo adjustment request recorded; inventory unchanged.');});
function inventoryPanel(s){const month=$('#to').value.slice(0,7),within=x=>x.date>=month+'-01'&&x.date<=month+'-31',movements=inventoryRecords().filter(within),trucks=truckRuns().filter(within),sum=(a,k)=>a.reduce((n,x)=>n+Number(x[k]||0),0),received=sum(data.food.filter(within),'pounds'),partner=sum(data.outgoing.filter(within),'pounds'),loaded=sum(trucks,'loaded'),returned=sum(trucks,'returned'),disposed=sum(movements.filter(x=>x.type==='disposal'),'pounds'),adjusted=sum(movements.filter(x=>x.type==='adjustment'),'pounds'),count=physicalCounts().find(x=>x.month===month),expected=count?count.opening+received-partner-loaded+returned-disposed+adjusted:null,variance=count?count.actual-expected:null;return '<div class="metrics">'+metric('Received (lb)',received,'Monthly receipts')+metric('Partner transfers (lb)',partner,'Outgoing to partners')+metric('Truck loaded (lb)',loaded,'Outbound truck loads')+metric('Truck returned (lb)',returned,'Recorded truck returns')+'</div><section class="card"><h2>Monthly inventory reconciliation · '+esc(month)+'</h2><p class="muted">Demonstration calculation only. Truck transfers and disposal are already part of the loaded truck weight and are not deducted twice. Client visit pounds and manually logged returns are not additionally deducted or added because they may overlap truck records.</p><div class="metrics">'+metric('Expected closing (lb)',expected===null?'—':Math.round(expected*100)/100,count?'Based on saved opening count':'Requires opening count')+metric('Physical closing (lb)',count?count.actual:'—','Entered count')+metric('Variance (lb)',variance===null?'—':Math.round(variance*100)/100,'Physical minus expected')+metric('Other disposal (lb)',disposed,'Separate manual movements')+'</div><form id="physicalCount" class="planning-form"><label>Month<input name="month" type="month" required value="'+esc(month)+'"></label><label>Opening count (lb)<input name="opening" type="number" min="0" step=".01" required value="'+(count?count.opening:'')+'"></label><label>Physical closing (lb)<input name="actual" type="number" min="0" step=".01" required value="'+(count?count.actual:'')+'"></label><label>Count notes<input name="notes" maxlength="180" value="'+esc(count?.notes||'')+'"></label><button class="primary">Save demo physical count</button></form><p class="muted">No month-end locks or approvals yet; Rachelle’s official process is still required.</p><button id="exportReconciliation">Export reconciliation CSV</button> <button id="printCountSheet">Print count worksheet</button></section><section class="card"><h2>Movement details</h2>'+table(['Movement','Pounds'],[['Incoming',fmt(received)],['Partner transfers',fmt(partner)],['Truck loaded',fmt(loaded)],['Truck returned',fmt(returned)],['Additional disposal',fmt(disposed)],['Signed adjustments',fmt(adjusted)],['Truck transfers (included in load)',fmt(sum(trucks,'transferred'))],['Truck disposal (included in load)',fmt(sum(trucks,'disposed'))]])+'</section><section class="card"><h2>Additional movements</h2><form id="inventoryEntry" class="planning-form"><label>Date<input name="date" type="date" required value="'+esc($('#to').value)+'"></label><label>Type<select name="type"><option value="return">Return (reference only)</option><option value="disposal">Additional disposal</option><option value="adjustment">Signed adjustment</option></select></label><label>Pounds<input name="pounds" type="number" step=".01" required></label><label>Notes<input name="notes" required></label><button class="primary">Save movement</button></form>'+table(['Date','Type','Pounds','Notes'],movements.map(x=>[esc(x.date),esc(x.type),fmt(x.pounds),esc(x.notes)]))+'<button id="exportInventory">Export movements CSV</button></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='inventoryEntry')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.pounds=Number(x.pounds);if(!Number.isFinite(x.pounds)||x.pounds===0||(x.type!=='adjustment'&&x.pounds<0))return;const all=inventoryRecords();all.push(x);localStorage.setItem(inventoryKey,JSON.stringify(all));render();toast('Demo inventory movement saved.');});
document.addEventListener('submit',e=>{if(e.target.id!=='physicalCount')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.opening=Number(x.opening);x.actual=Number(x.actual);if(!Number.isFinite(x.opening)||!Number.isFinite(x.actual)||x.opening<0||x.actual<0)return;const all=physicalCounts().filter(c=>c.month!==x.month);all.push(x);localStorage.setItem(countKey,JSON.stringify(all));render();toast('Physical count saved in demo.');});
const aggregateKey='bfp-demo-market-aggregates-v1';
function marketAggregates(){try{return JSON.parse(localStorage.getItem(aggregateKey))||[]}catch{return []}}
function aggregatePanel(){const rows=marketAggregates().filter(x=>x.month+'-01'>=$('#from').value.slice(0,7)+'-01'&&x.month+'-01'<=$('#to').value.slice(0,7)+'-01');return '<section class="card" style="margin-top:22px"><h2>Monthly aggregate reporting import</h2><p class="muted">For synthetic demonstration totals only. Do not import real PantrySoft exports, names, dates of birth, addresses, or any individual client records into this public browser demo.</p><p>Required CSV columns: <code>month,location,duplicated_households,unduplicated_households,duplicated_individuals,unduplicated_individuals,new_clients,outside_davis_percent,market_shifts</code>. Month format: YYYY-MM; location: bountiful. Reimporting a month replaces its earlier aggregate row.</p><button data-view="imports">Go to Data Import Center</button><p class="muted">Imported totals are shown separately from simulated visit calculations; they do not silently overwrite the board report.</p>'+table(['Month','Location','Duplicated households','Unduplicated households','Duplicated individuals','Unduplicated individuals','New clients','Outside Davis %','Shifts'],rows.map(x=>[esc(x.month),esc(x.location),fmt(x.duplicated_households),fmt(x.unduplicated_households),fmt(x.duplicated_individuals),fmt(x.unduplicated_individuals),fmt(x.new_clients),fmt(x.outside_davis_percent)+'%',fmt(x.market_shifts)]))+'</section>'}
function parseAggregateCsv(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const columns=['month','location','duplicated_households','unduplicated_households','duplicated_individuals','unduplicated_individuals','new_clients','outside_davis_percent','market_shifts'];if(lines.length<2||lines.length>121)throw Error('CSV must have a header and 1–120 aggregate rows.');const header=lines.shift().split(',').map(x=>x.trim());if(header.length!==columns.length||columns.some((x,i)=>header[i]!==x))throw Error('CSV columns do not match the aggregate template.');const results=[];for(const line of lines){if(!line.trim())continue;const cells=line.split(',').map(x=>x.trim());if(cells.length!==columns.length)throw Error('Invalid CSV row; use numeric aggregates without embedded commas.');const x=Object.fromEntries(columns.map((k,i)=>[k,cells[i]]));if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(x.month)||x.location!=='bountiful')throw Error('Use YYYY-MM and location bountiful.');for(const k of columns.slice(2)){if(!/^\d+(\.\d+)?$/.test(x[k]))throw Error('Only nonnegative numeric totals are allowed.');x[k]=Number(x[k]);if(!Number.isFinite(x[k]))throw Error('Invalid number.')}for(const k of columns.slice(2).filter(k=>k!=='outside_davis_percent'))if(!Number.isInteger(x[k]))throw Error('Counts and shifts must be whole numbers.');if(x.outside_davis_percent>100||x.unduplicated_households>x.duplicated_households||x.unduplicated_individuals>x.duplicated_individuals)throw Error('Aggregate totals are inconsistent.');results.push(x)}if(!results.length)throw Error('No rows found.');return results}
document.addEventListener('change',e=>{if(e.target.id==='demoRole'){demoRole=e.target.value;view='home';preview=false;render();window.scrollTo(0,0);return}if(e.target.id==='aggregateCsv')stageAggregate(e.target.files?.[0])})
const importTypes=[{id:'market',name:'Client Services / PantrySoft',desc:'Monthly aggregate household and individual totals',ready:true},{id:'offsite',name:'Off-site Services',desc:'Truck, bus and Mini Market tracking sheets'},{id:'food',name:'Food & Inventory',desc:'Receipts, rescue and warehouse reconciliations'},{id:'volunteers',name:'Volunteer Hours',desc:'Approved volunteer activity summaries'},{id:'engagement',name:'Community Engagement',desc:'Website, social media and newsletters'},{id:'financial',name:'Financial Reports',desc:'Monthly financial summary exports'}];
let selectedImport='market',stagedImport=null;
function importCenter(){const active=importTypes.find(x=>x.id===selectedImport)||importTypes[0];const history=importHistory();return '<p class="muted">Select a source, drop a file, review the results, and confirm. This public demo accepts <strong>synthetic aggregate data only</strong> — never actual client, donor or volunteer records.</p><div class="grid equal">'+importTypes.map(x=>'<section class="card"><h2>'+esc(x.name)+'</h2><p>'+esc(x.desc)+'</p><p class="muted">'+(x.ready?'Demo CSV importer ready':'Awaiting source CSV sample and field mapping')+'</p><button data-import="'+x.id+'">'+(x.ready?'Open importer':'View requirements')+'</button></section>').join('')+'</div><section class="card" style="margin-top:22px"><h2>'+esc(active.name)+'</h2>'+(active.ready?'<p>Use the sample-row template to prepare <strong>fictional monthly aggregate totals</strong>. Month format YYYY-MM; location code <code>bountiful</code> (lowercase); percentages are 0–100, not decimals; counts and shifts are whole numbers. Existing month/location rows are replaced only after confirmation. Actual PantrySoft CSV formats will need approved mapping before production.</p><button id="aggregateTemplate">Download CSV template</button><div id="importDrop" role="button" tabindex="0" style="border:2px dashed currentColor;border-radius:12px;padding:30px;text-align:center;margin:18px 0;cursor:pointer"><strong>Drop a synthetic CSV here</strong><p>or click to choose a file (maximum 50 KB)</p><input id="aggregateCsv" type="file" accept=".csv,text/csv" style="max-width:100%"></div><div id="importReview">'+(stagedImport?'<h3>Review before importing</h3><p>'+stagedImport.length+' monthly aggregate row(s) ready. Existing months will be replaced only after confirmation.</p>'+table(['Month','Location','Duplicated households','Unduplicated households','Duplicated individuals','Unduplicated individuals','New clients','Outside Davis %','Market shifts','Existing row'],stagedImport.map(x=>[esc(x.month),esc(x.location),fmt(x.duplicated_households),fmt(x.unduplicated_households),fmt(x.duplicated_individuals),fmt(x.unduplicated_individuals),fmt(x.new_clients),fmt(x.outside_davis_percent)+'%',fmt(x.market_shifts),marketAggregates().some(y=>y.month===x.month&&y.location===x.location)?'Will replace':'New']))+'<button class="primary" id="confirmAggregate">Confirm synthetic import</button> <button id="cancelAggregate">Cancel</button>':'<p class="muted">No file staged. Your data will not change until you confirm.</p>')+'</div>':'<p class="muted">This importer is not active yet. We need a sample export and approved field mapping before files can be routed safely. No data will be imported here.</p>')+'</section><section class="card" style="margin-top:22px"><h2>Recent demo imports</h2>'+table(['Imported at','Source','Reporting months','Rows'],history.slice(-12).reverse().map(x=>[esc(x.at),esc(x.source),esc(x.months),fmt(x.count)]))+'<p class="muted">This history is stored only in this browser. Production will require staff identity, audit history and permission controls.</p></section>'}
const importHistoryKey='bfp-demo-import-history-v1';
function importHistory(){try{return JSON.parse(localStorage.getItem(importHistoryKey))||[]}catch{return []}}
function stageAggregate(file){if(!file)return;if(file.size>50000){toast('CSV too large for aggregate demo.');return}file.text().then(t=>{stagedImport=parseAggregateCsv(t);render();toast('CSV validated. Review and confirm import.');}).catch(err=>{stagedImport=null;toast(err.message)})}
document.addEventListener('dragover',e=>{if(e.target.closest('#importDrop'))e.preventDefault()});
document.addEventListener('drop',e=>{if(!e.target.closest('#importDrop'))return;e.preventDefault();stageAggregate(e.dataTransfer.files[0])});
function importedMarketHeadline(){const from=$('#from').value,to=$('#to').value,loc=$('#location').value,month=from.slice(0,7),last=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate(),full=from===month+'-01'&&to===month+'-'+String(last).padStart(2,'0'),matching=marketAggregates().filter(x=>x.month===month&&x.location==='bountiful');if(!full||to.slice(0,7)!==month||loc==='north')return '<section class="card"><h2>Official monthly Market totals</h2><p class="muted">Select one complete calendar month to view imported monthly totals. The daily visit estimates below use a different source and are not added to imports.</p></section>';if(!matching.length)return '<section class="card"><h2>Official monthly Market totals · '+esc(month)+'</h2><p class="muted">No monthly aggregate has been imported for this period. Daily demonstration visits below are a separate source.</p><button data-view="imports">Import monthly Market totals</button></section>';const x=matching[0];return '<section class="card market-imported"><div class="section-head"><div><h2>Imported monthly Market totals · '+esc(month)+'</h2><p class="muted">Source: synthetic monthly aggregate CSV · Not verified or approved · Kept separate from daily demo visits</p></div><button data-view="imports">Review source import</button></div><div class="metrics">'+metric('Duplicated households',fmt(x.duplicated_households),'Monthly aggregate')+metric('Unduplicated households',fmt(x.unduplicated_households),'Monthly aggregate')+metric('Duplicated individuals',fmt(x.duplicated_individuals),'Monthly aggregate')+metric('Unduplicated individuals',fmt(x.unduplicated_individuals),'Monthly aggregate')+'</div>'+table(['Additional monthly measure','Imported value'],[['New clients',fmt(x.new_clients)],['Outside Davis County',fmt(x.outside_davis_percent)+'%'],['Market shifts',fmt(x.market_shifts)],['Average households / shift',x.market_shifts?(Number(x.duplicated_households)/Number(x.market_shifts)).toFixed(1):'—']])+'</section>'}
function marketReporting(visits){const households=new Map();for(const x of visits){const id=x.household;const row=households.get(id)||{size:0};row.size=Math.max(row.size,Number(x.size)||0);households.set(id,row)}const dupHouseholds=visits.length,dupIndividuals=visits.reduce((n,x)=>n+(Number(x.size)||0),0),undupHouseholds=households.size,householdMemberEstimate=[...households.values()].reduce((n,x)=>n+x.size,0),pounds=visits.reduce((n,x)=>n+(Number(x.pounds)||0),0);const shifts=new Set(visits.map(x=>x.date)).size;const fmtRatio=(a,b)=>b?(Math.round(a/b*100)/100).toLocaleString('en-US'):'—';return '<section class="card" style="margin-top:22px"><div class="section-head"><div><h2>Market reporting calculations</h2><p class="muted">Separate daily demo visit estimates, not the imported monthly totals above. These are not PantrySoft figures.</p></div><button id="exportMarket">Export Market summary</button></div><div class="metrics">'+metric('Duplicated households',dupHouseholds,'One per recorded Market visit')+metric('Unduplicated households',undupHouseholds,'Distinct household identifiers')+metric('Duplicated individuals',dupIndividuals,'Sum of members across visits')+metric('Estimated unique members',householdMemberEstimate,'Not verified individual identities')+'</div>'+table(['Measure','Calculated value','Basis'],[['Average pounds per household visit',fmtRatio(pounds,dupHouseholds)+' lb','Market pounds ÷ duplicated households'],['Average pounds per person-visit',fmtRatio(pounds,dupIndividuals)+' lb','Market pounds ÷ duplicated individuals'],['Average households per active date',fmtRatio(dupHouseholds,shifts),'Visits ÷ dates with recorded visits; not actual staffed shifts'],['New clients','Awaiting aggregate import','First-ever client status cannot be confirmed from this demo'],['Outside Davis County (%)','Awaiting aggregate import','City Other is not evidence of county of residence']])+'<p class="muted">For actual Market shifts, verified unduplicated individuals, new clients, and county-of-residence percentages, import approved aggregate PantrySoft figures. No individual client records should be uploaded to this public demo.</p></section>'}

function offsiteReconciliationPanel(){const from=$('#from').value,to=$('#to').value,runs=truckRuns().filter(x=>x.date>=from&&x.date<=to),visits=scope(data.visits).filter(x=>x.program==='Mobile Truck'||x.program==='Mobile Bus'),byStop=new Map();for(const x of visits){const k=x.program+'|'+(x.stop||'Unassigned');const row=byStop.get(k)||{program:x.program,stop:x.stop||'Unassigned',visits:0,people:0};row.visits++;row.people+=Number(x.size)||0;byStop.set(k,row)}return '<section class="card"><h2>Off-site service and load cross-check</h2><p class="muted">Visit counts and truck weights are different source records. A stop may have service visits without a matching truck run. Bus service pounds are never estimated from truck loads.</p>'+table(['Channel','Stop','Visits','Person-visits','Matching truck runs'],[...byStop.values()].map(x=>[esc(x.program),esc(x.stop),fmt(x.visits),fmt(x.people),x.program==='Mobile Bus'?'Not applicable':fmt(runs.filter(r=>r.stop===x.stop).length)]))+'<p class="muted">Truck runs without recorded service stops: '+fmt(runs.filter(r=>!visits.some(v=>v.program==='Mobile Truck'&&v.stop===r.stop)).length)+'. This is a review prompt, not proof of missing service.</p></section>'}

function offsiteLocations(visits){const groups=new Map();for(const x of visits){const stop=(x.stop||'Unassigned / historical demo').trim();const key=x.program+'|'+stop;const row=groups.get(key)||{program:x.program,stop,visits:0,people:0,households:new Set()};row.visits++;row.people+=Number(x.size)||0;row.households.add(x.household);groups.set(key,row)}return '<section class="card" style="margin-top:22px"><h2>Service by off-site location</h2><p class="muted">Location is the service stop, not the household’s residential city. Historical demo visits without a stop remain unassigned rather than being attributed to a guessed location.</p>'+table(['Program','Service stop','Visits','Person-visits','Unique households'],[...groups.values()].sort((a,b)=>b.visits-a.visits).map(x=>[esc(x.program),esc(x.stop),fmt(x.visits),fmt(x.people),fmt(x.households.size)]))+'</section>'}
const truckKey='bfp-demo-truck-runs-v1';
function truckRuns(){try{return JSON.parse(localStorage.getItem(truckKey))||[]}catch{return []}}
function truckPanel(){const rows=truckRuns().filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value),sum=k=>rows.reduce((n,x)=>n+Number(x[k]||0),0);return '<section class="card" style="margin-top:22px"><div class="section-head"><div><h2>Mobile Truck load reconciliation</h2><p class="muted">Track food leaving the warehouse and food returning. Truck load totals are separate from household service visits, so they are not added to client counts.</p></div><button id="exportTruck">Export runs CSV</button></div><div class="metrics">'+metric('Loaded (lb)',sum('loaded'),'Outbound weight')+metric('Returned (lb)',sum('returned'),'Unused food returned')+metric('Transferred (lb)',sum('transferred'),'To other organizations')+metric('Reconciled distribution (lb)',sum('distributed'),'Loaded − returned − transfers − disposal')+'<div class="notice"><strong>Average distributed pounds per truck run:</strong> '+(rows.length?fmt(Math.round(sum('distributed')/rows.length*100)/100):'—')+' lb across '+fmt(rows.length)+' recorded run(s). This is not pounds per household or pounds per bus service.</div></div><form id="truckEntry" class="planning-form"><label>Run date<input name="date" type="date" required value="'+esc($('#to').value)+'"></label><label>Service location / stop<input name="stop" type="text" required placeholder="Demo community partner"></label><label>Loaded (lb)<input name="loaded" type="number" min="0" step="0.01" required></label><label>Returned (lb)<input name="returned" type="number" min="0" step="0.01" value="0" required></label><label>Transferred to partners (lb)<input name="transferred" type="number" min="0" step="0.01" value="0" required></label><label>Disposed (lb)<input name="disposed" type="number" min="0" step="0.01" value="0" required></label><button class="primary" type="submit">Reconcile demo run</button></form><p class="muted">These weights are demonstration-only. Confirm Tryn’s exact reconciliation rules before using production reports. Do not record the same return a second time as an inventory adjustment.</p>'+table(['Date','Stop','Loaded','Returned','Transfers','Disposal','Distributed'],rows.map(x=>[esc(x.date),esc(x.stop),fmt(x.loaded),fmt(x.returned),fmt(x.transferred),fmt(x.disposed),fmt(x.distributed)]))+'</section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='truckEntry')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));for(const k of ['loaded','returned','transferred','disposed'])x[k]=Number(x[k]);if(['loaded','returned','transferred','disposed'].some(k=>!Number.isFinite(x[k])||x[k]<0)||x.returned+x.transferred+x.disposed>x.loaded){toast('Check weights: returned, transferred and disposed cannot exceed loaded.');return}x.distributed=Math.round((x.loaded-x.returned-x.transferred-x.disposed)*100)/100;const all=truckRuns();all.push(x);localStorage.setItem(truckKey,JSON.stringify(all));render();toast('Demo truck run reconciled.');});

const donorKey='bfp-demo-donor-directory-v1';
function donorDirectory(){try{const x=JSON.parse(localStorage.getItem(donorKey));return Array.isArray(x)?x:[]}catch{return []}}
function donorSummary(){const by=new Map();for(const x of data.food.filter(x=>x.source==='Community donation'&&x.partner&&x.partner.trim().toLowerCase()!=='door')){const name=x.partner.trim(),key=name.toLowerCase(),d=by.get(key)||{name,receipts:0,pounds:0,last:''};d.receipts++;d.pounds+=Number(x.pounds)||0;if(x.date>d.last)d.last=x.date;by.set(key,d)}return [...by.values()].sort((a,b)=>b.pounds-a.pounds)}
function donorDirectoryPanel(){const rows=donorSummary(),details=donorDirectory();return '<section class="card"><h2>Food donor directory</h2><p class="muted">Named community donors only. Grocery Rescue, anonymous door donations, and partner transfers are excluded. Contacts are fictional demo entries saved in this browser; never enter real personal information here.</p><form id="donorContact" class="planning-form"><label>Donor name<input name="name" required maxlength="100" placeholder="Match name on receipt"></label><label>Contact / organization role<input name="contact" maxlength="100"></label><label>Preferred acknowledgement<select name="preference"><option>Print letter</option><option>Email later (not connected)</option><option>No acknowledgement</option></select></label><label>Internal demo note<input name="notes" maxlength="180"></label><button class="primary">Save donor preference</button></form>'+table(['Donor','Receipts','Food donated (lb)','Latest receipt','Acknowledgement','Action'],rows.map(x=>{const d=details.find(y=>y.name.toLowerCase()===x.name.toLowerCase());return [esc(x.name),fmt(x.receipts),fmt(x.pounds),esc(x.last),esc(d?.preference||'Print letter'),'<button data-donor="'+esc(x.name)+'">Prepare letter</button>']}))+'<button id="exportDonors">Export donor history CSV</button></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='donorContact')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.name=x.name.trim();if(!donorSummary().some(y=>y.name.toLowerCase()===x.name.toLowerCase())){toast('Enter a donor name already in the demo receipt history.');return}const all=donorDirectory().filter(y=>y.name.toLowerCase()!==x.name.toLowerCase());all.push(x);localStorage.setItem(donorKey,JSON.stringify(all));render();toast('Demo donor preference saved.');});


const driveKey='bfp-demo-food-drives-v1';
function foodDrives(){try{const x=JSON.parse(localStorage.getItem(driveKey));return Array.isArray(x)?x:[]}catch{return []}}
function foodDrivePanel(){const rows=foodDrives(),from=$('#from').value,to=$('#to').value,active=rows.filter(x=>x.start<=to&&x.end>=from),received=active.reduce((n,x)=>n+Number(x.pounds||0),0);return '<div class="metrics">'+metric('Food drives in period',active.length,'Overlapping selected dates')+metric('Drive pounds reported',received,'Separate manual demo totals; not included in receipts')+'</div><section class="card"><h2>Community food drives</h2><p class="muted">Track drive planning, organizers and outcomes. These manually entered drive pounds are not automatically added to incoming food, preventing double counting. Reconcile with actual receipts before production.</p><form id="foodDriveEntry" class="planning-form"><input name="id" type="hidden"><label>Drive / campaign<input name="name" maxlength="120" required></label><label>Organizer<input name="organizer" maxlength="120" required></label><label>Start<input name="start" type="date" required></label><label>End<input name="end" type="date" required></label><label>Goal (lb)<input name="goal" type="number" min="0" step=".01" required></label><label>Reported outcome (lb)<input name="pounds" type="number" min="0" step=".01" required></label><label>Status<select name="status"><option>Planning</option><option>Active</option><option>Completed</option><option>Cancelled</option></select></label><label>Notes<input name="notes" maxlength="180"></label><button class="primary">Save food drive</button><button type="reset">Clear</button></form></section><section class="card"><h2>Drive register</h2>'+table(['Drive','Organizer','Dates','Status','Goal','Reported','Progress','Manage'],rows.map(x=>[esc(x.name),esc(x.organizer),esc(x.start)+' to '+esc(x.end),esc(x.status),fmt(x.goal),fmt(x.pounds),x.goal?(x.pounds/x.goal*100).toFixed(1)+'%':'—','<button data-edit-drive="'+esc(x.id)+'">Edit</button> <button data-delete-drive="'+esc(x.id)+'">Delete</button>']))+'<button id="exportDrives">Export drives CSV</button></section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='foodDriveEntry')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.goal=Number(x.goal);x.pounds=Number(x.pounds);if(x.end<x.start||![x.goal,x.pounds].every(n=>Number.isFinite(n)&&n>=0)){toast('Check dates and pounds.');return}x.id=x.id||'drive-'+Date.now();const all=foodDrives().filter(y=>y.id!==x.id);all.push(x);localStorage.setItem(driveKey,JSON.stringify(all));render();toast('Demo food drive saved.');});


const thanksKey='bfp-demo-donor-thanks-v1';
function thankRecords(){try{const x=JSON.parse(localStorage.getItem(thanksKey));return Array.isArray(x)?x:[]}catch{return []}}
function acknowledgementPanel(){const rows=donorSummary(),saved=thankRecords(),from=$('#from').value,to=$('#to').value;return '<section class="card"><h2>Donor acknowledgement review</h2><p class="muted">Staff can record a demo acknowledgement status for the selected reporting dates. Printing a letter does not mark it sent. No email or postal integration is connected. Only mark Sent externally if an actual off-system acknowledgement was made (fictional demo records only).</p>'+table(['Donor','Latest donation','Acknowledgement status','Update status'],rows.map(x=>{const record=saved.find(y=>y.donor.toLowerCase()===x.name.toLowerCase()&&y.from===from&&y.to===to),preference=donorDirectory().find(y=>y.name.toLowerCase()===x.name.toLowerCase())?.preference||'Print letter';return [esc(x.name),esc(x.last),esc(record?.status||'Not recorded')+' · '+esc(preference),'<button data-ack-donor="'+esc(x.name)+'" data-ack-status="Reviewed">Reviewed</button> <button data-ack-donor="'+esc(x.name)+'" data-ack-status="Sent externally">Sent externally</button> <button data-ack-donor="'+esc(x.name)+'" data-ack-status="Not required">Not required</button>']}))+'<button id="exportThanks">Export acknowledgement log CSV</button></section>'}


function foodCategorySummary(){const from=$('#from').value,to=$('#to').value,loc=$('#location').value,receipts=data.food.filter(x=>x.date>=from&&x.date<=to&&(loc==='all'||x.location===loc)),transfers=data.outgoing.filter(x=>x.date>=from&&x.date<=to&&(loc==='all'||x.location===loc)),categories=[...new Set([...receipts.map(x=>x.category),...transfers.map(x=>x.category)].filter(Boolean))].sort();return categories.map(category=>({category,received:receipts.filter(x=>x.category===category).reduce((n,x)=>n+Number(x.pounds||0),0),transferred:transfers.filter(x=>x.category===category).reduce((n,x)=>n+Number(x.pounds||0),0)}))}
function foodCategoryPanel(){const rows=foodCategorySummary();return '<section class="card"><div class="section-head"><div><h2>Food by category</h2><p class="muted">Recorded receipt and partner-transfer weights by the categories currently used in this demo.</p></div><button id="exportFoodCategories">Export CSV</button></div>'+table(['Recorded category','Received (lb)','Partner transfers (lb)','Difference (lb)'],rows.map(x=>[esc(x.category),fmt(x.received),fmt(x.transferred),fmt(x.received-x.transferred)]))+'<p class="muted">Difference is not on-hand inventory: household service, truck movements, disposal, and opening stock are excluded. Official Utah Food Bank category mapping awaits confirmation; no categories have been invented.</p></section>'}


function donorContributionRows(){const from=$('#from').value,to=$('#to').value,loc=$('#location').value,rows=data.food.filter(x=>x.source==='Community donation'&&x.date>=from&&x.date<=to&&(loc==='all'||x.location===loc)),groups=new Map();for(const x of rows){const name=(x.partner||'Anonymous / door donation').trim()||'Anonymous / door donation',key=name.toLowerCase(),item=groups.get(key)||{name,receipts:0,pounds:0,first:x.date,last:x.date};item.receipts++;item.pounds+=Number(x.pounds)||0;if(x.date<item.first)item.first=x.date;if(x.date>item.last)item.last=x.date;groups.set(key,item)}return [...groups.values()].sort((a,b)=>b.pounds-a.pounds)}
function donorContributionPanel(){const rows=donorContributionRows(),total=rows.reduce((n,x)=>n+x.pounds,0);return '<section class="card"><div class="section-head"><div><h2>Community donation contributions</h2><p class="muted">Food donations recorded in the selected dates and location. Grocery Rescue is a separate source, and food-drive planning totals are not added.</p></div><button id="exportDonorContributions">Export CSV</button></div><div class="metrics">'+metric('Community donation pounds',total,'Recorded receipt weights')+metric('Named / anonymous sources',rows.length,'Distinct receipt-source labels')+'</div>'+table(['Donor / source','Receipts','Received (lb)','First receipt','Latest receipt'],rows.map(x=>[esc(x.name),fmt(x.receipts),fmt(x.pounds),esc(x.first),esc(x.last)]))+'<p class="muted">Receipt names may need cleanup before use for donor recognition. This is a synthetic operations report, not a monetary valuation or tax acknowledgement.</p></section>'}


function driveReconciliationRows(){const from=$('#from').value,to=$('#to').value,receipts=data.food.filter(x=>x.source==='Community donation'&&x.date>=from&&x.date<=to),drives=foodDrives().filter(x=>x.start<=to&&x.end>=from);return drives.map(d=>{const matches=receipts.filter(x=>x.date>=d.start&&x.date<=d.end&&(x.partner||'').trim().toLowerCase()===d.organizer.trim().toLowerCase()),actual=matches.reduce((n,x)=>n+Number(x.pounds||0),0);return {drive:d.name,organizer:d.organizer,reported:Number(d.pounds||0),actual,receipts:matches.length,difference:Number(d.pounds||0)-actual}})}
function driveReconciliationPanel(){const rows=driveReconciliationRows();return '<section class="card"><div class="section-head"><div><h2>Food-drive receipt review</h2><p class="muted">Compare a drive organizer’s reported outcome with matching community-donation receipts dated during the drive.</p></div><button id="exportDriveReconciliation">Export CSV</button></div>'+table(['Drive','Organizer','Reported (lb)','Matching receipts','Receipt pounds','Difference (lb)'],rows.map(x=>[esc(x.drive),esc(x.organizer),fmt(x.reported),fmt(x.receipts),fmt(x.actual),fmt(x.difference)]))+'<p class="muted">Matching is a suggestion based on exact organizer/receipt donor names and dates; it is not proof that a receipt belongs to a particular drive. Shared organizers and unmatched names require staff review. Neither amount is posted again to inventory.</p></section>'}


function donationActionSummary(){const from=$('#from').value,to=$('#to').value,donors=donorContributionRows(),drives=foodDrives().filter(x=>x.start<=to&&x.end>=from),directory=donorDirectory(),unack=donors.filter(x=>x.name!=='Anonymous / door donation'&&directory.find(y=>y.name.toLowerCase()===x.name.toLowerCase())?.preference!=='No acknowledgement'&&!thankRecords().some(t=>t.donor.toLowerCase()===x.name.toLowerCase()&&t.from===from&&t.to===to)),unmatched=driveReconciliationRows().filter(x=>Math.abs(x.difference)>0.01);return {donors,drives,unack,unmatched}}
function donationActionPanel(){const x=donationActionSummary();return '<section class="card"><div class="section-head"><div><h2>Follow-up work</h2><p class="muted">Choose the work you need to do. Counts are for the selected reporting dates; these are demo prompts, not assigned tasks.</p></div></div><div class="metrics">'+metric('Donors to review',x.unack.length,'No acknowledgement status for this period')+metric('Drive differences',x.unmatched.length,'Reported vs candidate receipt totals')+metric('Food drives',x.drives.length,'Overlapping the reporting period')+'</div><div class="toolbar" style="display:flex;flex-wrap:wrap;gap:8px"><button data-food-section="thanksReview">Review thank-you letters</button><button data-food-section="driveReview">Check food-drive totals</button><button data-food-section="foodDonors">Open donor reporting</button></div></section>'}


function donorLetterPreviewPanel(){const x=donorContributionRows().filter(r=>r.name!=='Anonymous / door donation'),dir=donorDirectory(),pending=x.filter(r=>dir.find(d=>d.name.toLowerCase()===r.name.toLowerCase())?.preference!=='No acknowledgement'&&!thankRecords().some(t=>t.donor.toLowerCase()===r.name.toLowerCase()&&t.from===$('#from').value&&t.to===$('#to').value&&t.status==='Sent externally'));return '<section class="card"><div class="section-head"><div><h2>Prepare donor thank-you letters</h2><p class="muted">Choose a donor to prepare one printable letter, or prepare letters for all eligible donors in the selected dates. Review names and weights before mailing.</p></div><button id="printDonorLetters">Prepare all eligible letters</button></div>'+table(['Donor','Food donated (lb)','Receipts','Letter'],pending.map(r=>[esc(r.name),fmt(r.pounds),fmt(r.receipts),'<button data-donor="'+esc(r.name)+'">Prepare letter</button>']))+'<p class="muted">All letters are visibly marked as fictional demonstrations and are not sent automatically.</p></section>'}


function foodPeriodSummary(){const x=donationActionSummary(),categories=foodCategorySummary(),received=categories.reduce((n,c)=>n+c.received,0),transferred=categories.reduce((n,c)=>n+c.transferred,0);return [['Section','Measure','Selected period','Value','Source / interpretation'],['Food','Recorded receipts', $('#from').value+' to '+$('#to').value,received,'Food receipt ledger; includes Grocery Rescue'],['Food','Recorded partner transfers',$('#from').value+' to '+$('#to').value,transferred,'Outgoing partner transfer ledger; not net stock'],['Donors','Community donation sources',$('#from').value+' to '+$('#to').value,x.donors.length,'Includes anonymous source labels'],['Donors','Acknowledgements to review',$('#from').value+' to '+$('#to').value,x.unack.length,'No saved status for selected period'],['Food drives','Overlapping drives',$('#from').value+' to '+$('#to').value,x.drives.length,'Manual drive register; not added to receipts'],['Food drives','Potential reconciliation differences',$('#from').value+' to '+$('#to').value,x.unmatched.length,'Exact organizer-name matching only'],...categories.map(c=>['Category',c.category,$('#from').value+' to '+$('#to').value,c.received,'Receipt pounds; not inventory on hand'])]}
function donationExportPanel(){return '<section class="card"><div class="section-head"><div><h2>Donation reporting packet</h2><p class="muted">One export for the selected period. Every figure retains its source label so reported drive outcomes are never added to receipt weights.</p></div><button id="exportDonationPacket">Export reporting packet CSV</button></div></section>'}


function foodWorkspaceGuide(){return '<section class="card"><h2>How this works</h2><p><strong>1.</strong> Record an incoming donation or Grocery Rescue receipt when food arrives.</p><p><strong>2.</strong> Record a partner transfer separately when food leaves for another organization.</p><p><strong>3.</strong> Use the donation management tabs for food drives, thank-you letters and reporting. Food-drive planning weights never change inventory.</p><p class="muted">This is a public demonstration using fictional, browser-local records. Actual pantry operations require staff access controls, validated categories and approved data sources.</p></section>'}

function donorHistory(food){const groups=new Map();for(const x of food){const name=(x.partner||'Door').trim();const key=name.toLowerCase();const current=groups.get(key)||{name,count:0,pounds:0};current.count++;current.pounds+=Number(x.pounds)||0;groups.set(key,current)}return table(['Donor','Receipts','Pounds received'],[...groups.values()].sort((a,b)=>b.pounds-a.pounds).map(x=>[esc(x.name),fmt(x.count),fmt(x.pounds)]))}
function printDonorLetters(onlyDonor=''){const from=$('#from').value,to=$('#to').value;const directory=donorDirectory();const rows=stats().f.filter(x=>x.source==='Community donation'&&(x.partner||'').trim()&&(x.partner||'').trim().toLowerCase()!=='door'&&(!onlyDonor||x.partner.trim().toLowerCase()===onlyDonor.toLowerCase())&&directory.find(y=>y.name.toLowerCase()===x.partner.trim().toLowerCase())?.preference!=='No acknowledgement');const groups=new Map();for(const x of rows){const name=(x.partner||'').trim();if(!name)continue;const key=name.toLowerCase();const current=groups.get(key)||{name,count:0,pounds:0};current.count++;current.pounds+=Number(x.pounds)||0;groups.set(key,current)}if(!groups.size){toast('No named community donors in the selected dates.');return}const pages=[...groups.values()].map(x=>'<article style="break-after:page;padding:45px;font-family:Georgia,serif"><h2>Bountiful Food Pantry</h2><p>DEMONSTRATION LETTER — NOT FOR MAILING</p><p>'+esc(to)+'</p><p>Dear '+esc(x.name)+',</p><p>Thank you for supporting Bountiful Food Pantry. During '+esc(from)+' through '+esc(to)+', our records show '+fmt(x.count)+' food donation(s), totaling '+fmt(x.pounds)+' pounds.</p><p>Your generosity helps us serve our neighbors.</p><p>With gratitude,<br>Bountiful Food Pantry</p><small>Fictional demonstration data. Verify donor identity, address and totals before production mailing.</small></article>').join('');const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print donor letters.');return}w.document.write('<!doctype html><html><head><title>Demo donor letters</title></head><body>'+pages+'</body></html>');w.document.close();w.focus();w.print()}
function clientRows(){let q=$('#search').value.toLowerCase(),c=$('#channel').value,v=stats().v.filter(x=>(!c||x.program===c)&&[x.household,x.city,x.id].join(' ').toLowerCase().includes(q));$('#clientRows').innerHTML=table(['Household','City','Members','Channel','Date','Action'],v.slice().reverse().slice(0,50).map(x=>[`<strong>${esc(x.household)}</strong><div class="muted">${x.id}</div>`,esc(x.city),x.size,esc(x.program),x.date,`<button data-repeat="${x.id}">Record visit</button>`]))}
let entryType='service';function weightFields(kind){return '<fieldset style="border:1px solid #ccd8cd;border-radius:12px;padding:12px"><legend>Scale entry (pounds)</legend><label>Gross scale weight (lb)<input required name="gross" type="number" min="0" step="0.01" value="'+(kind==='food'?'220':'120')+'"></label><label>Container / tare type<select name="tareType"><option value="none">No container</option><option value="small">Small Gaylord — example 20 lb</option><option value="large">Large Gaylord — example 35 lb</option><option value="pallet">Pallet — example 45 lb</option><option value="custom">Custom tare</option></select></label><label>Custom tare (lb, only when custom selected)<input name="customTare" type="number" min="0" step="0.01" value="0"></label><p class="muted">Net weight = gross − tare. Container weights are illustrative placeholders until Rachelle confirms the real tare schedule. The saved entry stores all weights.</p></fieldset>'}
function openEntry(type='service',program='Market',repeat){entryType=type;$('#modalTitle').textContent=type==='food'?'Receive food':type==='outgoing'?'Record outgoing food':type==='packs'?'Record completed packs':'Record a service visit';let field=(label,name,kind='text',val='',min='')=>`<label>${label}<input required name="${name}" type="${kind}" value="${esc(val)}" ${min?'min="'+min+'"':''}></label>`,select=(label,name,options,val)=>`<label>${label}<select name="${name}">${options.map(c=>`<option ${val===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;$('#fields').innerHTML=field('Activity date','date','date',$('#to').value)+(type==='service'?field('Demo household name','household','text',repeat?.household||'')+field('Household members','size','number',repeat?.size||3,'1')+select('Home community','city',cities,repeat?.city)+select('Service channel','program',channels,program)+field('Food distributed (lb)','pounds','number',30,'1')+(program==='Mobile Truck'||program==='Mobile Bus'||program==='Mini Market'?'<label>Off-site stop / location<input name="stop" type="text" required placeholder="Demo location name"></label>':''):type==='outgoing'?field('Destination pantry / partner','partner')+select('Food category','category',['Produce','Dry goods','Dairy','Protein','Bakery','Frozen','Other'])+weightFields('outgoing'):type==='food'?select('Source','source',['Grocery Rescue','Community donation'])+field('Donor name (or Door for anonymous)','partner')+select('Food category','category',['Produce','Dry goods','Dairy','Protein'])+weightFields('food'):field('Packs completed','count','number',100,'1'));$('#modal').showModal()}
$('#entry').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));for(let key of ['size','pounds','count'])if(x[key])x[key]=Number(x[key]);if(entryType==='food'||entryType==='outgoing'){const tare={none:0,small:20,large:35,pallet:45,custom:Number(x.customTare||0)}[x.tareType];x.gross=Number(x.gross);x.tare=Number(tare);x.pounds=Math.round((x.gross-x.tare)*100)/100;if(!Number.isFinite(x.pounds)||x.pounds<=0){toast('Net weight must be greater than zero. Check gross and tare weights.');return;}}x.location='bountiful';x.id='DEMO-'+Date.now();if(entryType==='service')data.visits.push(x);else if(entryType==='food')data.food.push(x);else if(entryType==='outgoing')data.outgoing.push(x);else data.packs.push(x);save();$('#modal').close();render();toast('Record saved. Dashboards and reports updated.');};
